from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(n):
        return 0 <= n[0] < rows and 0 <= n[1] < cols and grid[n[0]][n[1]] == '.'

    def nears(n):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            yield (n[0]+dr, n[1]+dc)

    queue = deque([start])
    seen = {start}

    while queue:
        n = queue.popleft()
        if n == goal:
            path = [n]
            while n != start:
                n = (n[0]-1, n[1]-1)
                path.insert(0, n)
            return path

        for nn in nears(n):
            if is_valid(nn) and nn not in seen:
                queue.append(nn)
                seen.add(nn)

    return []
