from collections import deque

def solve(grid, start, goal):
    if start == goal:
        return [start]
    if grid[start[0]][start[1]] == '#':
        return []
    rows = len(grid)
    cols = len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    dq = deque([(start, [start])])
    visited = set([start])
    while dq:
        row, path = dq.popleft()
        if (row, path[-1]) == goal:
            return path
        for dr, dc in directions:
            r, c = row[0] + dr, row[1] + dc
            if (0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited):
                dq.append(((r, c), path + [(r, c)])
                visited.add((r, c))
            elif (0 <= r < rows and 0 <= c < cols and grid[r][c] == '#'):
                visited = visited.union([(r, c + i, c + j) for i in range(rows) for j in range(cols)])
    return []
