def solve(grid, start, goal):
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def dfs(cell, path):
        if cell == goal:
            return path + [cell]
        if start == cell and goal == start:
            return [start]
        if cell in path:
            return []
        path.append(cell)
        for m in movements:
            new_cell = (cell[0] + m[0], cell[1] + m[1])
            if is_valid(new_cell) and dfs(new_cell, path):
                return path
        path.pop()
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    for movement in movements:
        new_cell = (start[0] + movement[0], start[1] + movement[1])
        if is_valid(new_cell):
            return dfs(new_cell, [])
    return []
