                    result = foreach_unvisited_cell(new_row, new_col, new_path, explored)
                    if result:
                        return result
            return None

    def yield_immediate_explored_neighbours(row, col, visited):
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and grid[new_row][new_col] != '#' and (new_row, new_col) not in visited:
                yield (new_row, new_col)

    def for_start_and_goal_neighbours(starts):
        for start in starts:
            for goal in starts:
                if start != goal:
                    yield start, goal

    start_orig = start
    visited = set()
    explored = set()
    queues = [{start: [] if start == goal else (start,)}]
    while queues:
        queue_on_stack = [item for queue in queues for item in queue]
        for item in queue_on_stack:
            if item not in visited:
                queue = [list(item) for item in item]
                path = queue[-1]
                if path[-1] not in visited:
                    visited.add(path[-1])
                    if path[-1] == start_orig:
                        if path[0] == goal:
                            return path
                    for next_row, next_col in yield_immediate_explored_neighbours(*path[-1], visited | set(path)):
                        if path[-1] != start and next_row, next_col not in explored:
                            explored.add(next_row, next_col)
                            queues[0].append((next_row, next_col))
    return []

